import fs from 'node:fs';import path from 'node:path';import zlib from 'node:zlib';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';
const root=path.resolve('runtime'),load=p=>import(pathToFileURL(path.join(root,p)));
const {RemoteD1Database}=await load('report2-d1-adapter.mjs');
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN);
const request=db._request.bind(db);db._request=async payload=>{const sqls=payload.op==='batch'?payload.statements.map(s=>s.sql):[payload.sql];assert.ok(['all','first','batch','raw'].includes(payload.op));for(const sql of sqls)assert.ok(/^\s*(SELECT|WITH|PRAGMA table_info|EXPLAIN QUERY PLAN)\b/i.test(sql)&&!/\b(INSERT|UPDATE|DELETE|CREATE|DROP|ALTER|REPLACE)\b/i.test(sql));const u=db.usageSnapshot();assert.ok(u.rows_read<800&&u.rows_written===0&&u.unknown_ops===0&&u.requests<24);return request(payload);};
const RUN='1791224954306-1791224965631',T=1791225050790;
const file=path.join(root,'src/v3-telegram-lifecycle-sidecar.mjs'),source=fs.readFileSync(file,'utf8');
const tables=[...new Set([...source.matchAll(/\b(?:FROM|JOIN)\s+([a-z][a-z0-9_]+)/gi)].map(m=>m[1]))].filter(t=>t!=='json_each'&&t!=='ranked');
const records={};let handoffs=null;try{const api=await load('src/v3-telegram-lifecycle-sidecar.mjs');handoffs=await api.loadCompletedLifecycleHandoffs(db,{source_run_id:RUN,now_ts:T});}catch(e){handoffs={error:String(e.message).slice(0,160)};}
records.canonical_publication_shadow=(await db.prepare('SELECT * FROM canonical_publication_shadow WHERE run_id=?1 AND contract_code IN (?2,?3) ORDER BY created_ts DESC LIMIT 2').bind(RUN,'ZEC-USDT','FIL-USDT').all()).results;
const skipped=[];
for(const table of tables.slice(0,8)){try{if(db.usageSnapshot().rows_read>=700)break;const cols=(await db.prepare('PRAGMA table_info('+table+')').all()).results.map(c=>c.name);const run=cols.includes('source_run_id')?'source_run_id':cols.includes('run_id')?'run_id':null;const contract=cols.includes('contract_code')?'contract_code':cols.includes('contract')?'contract':null;if(!run||!contract){skipped.push({table,reason:'NO_EXACT_RUN_CONTRACT_COLUMNS',columns:cols});continue;}const sql='SELECT * FROM '+table+' WHERE '+run+'=?1 AND '+contract+' IN (?2,?3) LIMIT 6',plan=(await db.prepare('EXPLAIN QUERY PLAN '+sql).bind(RUN,'ZEC-USDT','FIL-USDT').all()).results;if(plan.some(p=>/^SCAN\s/i.test(p.detail)&&!p.detail.includes('USING INDEX'))){skipped.push({table,reason:'UNBOUNDED_PLAN_REJECTED',plan});continue;}records[table]=(await db.prepare(sql).bind(RUN,'ZEC-USDT','FIL-USDT').all()).results;}catch(e){skipped.push({table,error:String(e.message).slice(0,160)});}}
fs.mkdirSync('audit-output',{recursive:true});fs.writeFileSync('audit-output/exact-lifecycle-read.json',JSON.stringify({schema:'report2-exact-same-run-readonly-diagnosis-v1',run_id:RUN,original_cutoff:T,read_at:Date.now(),sourceHTTP:0,MAIN:0,Telegram:0,tables,handoffs,records,skipped,usage:db.usageSnapshot(),secrets_included:false},null,2));
const worker=fs.readFileSync(path.join(root,'src/worker.js'),'utf8').replace(/from (['"])\.\/([^'"\n]+)\1/g,(_,q,name)=>'from '+JSON.stringify(pathToFileURL(path.join(root,'src',name)).href));
const api=await import('data:text/javascript;base64,'+Buffer.from(worker+'\nexport { buildTrajectoryWindow, sortedTrades, flattenTrades, normalizeKlines };\n').toString('base64'));
const {buildHtxFuturesFlowPrimary}=await load('src/candidate-evidence-v2-runtime.mjs');
const saved=zlib.gunzipSync(fs.readFileSync('checkpoints/signed-tape-source-bodies-20261004.json.gz')),receipts=JSON.parse(saved),rows=[];
for(const symbol of ['NEAR','SOL']){const contract=symbol+'-USDT',r=receipts.filter(r=>r.url.includes('contract_code='+contract));for(const e of r)assert.equal(crypto.createHash('sha256').update(e.body).digest('hex'),e.sha256);const body=part=>JSON.parse(r.find(e=>e.url.includes(part)).body),now=Math.max(...r.map(e=>e.observed_ts)),info=body('/swap_contract_info?').data.find(i=>i.contract_code===contract),end=Math.floor(now/60000)*60000,start=end-240*60000;
const trades=api.flattenTrades(body('/history/trade?').data),klines=api.normalizeKlines(body('/history/kline?'));const window=api.buildTrajectoryWindow({label:'4h',startMs:start,endMs:end,klines,orderedTrades:api.sortedTrades(trades),contractSize:info.contract_size,minTrades:50,oi:null});const trajectory={source:'HTX official public API',market:'HTX USDT-M Futures',contract,contract_info:info,timestamp:now,windows:{'4h':window},coverage:{flow_4h:window.order_flow.usable?'closed':'not_closed'}};const result=buildHtxFuturesFlowPrimary({contract,trajectory,now});rows.push({contract,original_clock:now,source_hashes:r.map(r=>r.sha256),raw_fills:trades.length,flow:window.order_flow,price:window.price,result});}
fs.writeFileSync('audit-output/saved-actual-four-hour-flow.json',JSON.stringify({schema:'report2-original-clock-actual-four-hour-flow-diagnosis-v1',historical_only:true,sourceHTTP:0,MAIN:0,Telegram:0,rows},null,2));console.log(JSON.stringify({status:'BOUNDED_READ_AND_ORIGINAL_CLOCK_REPLAY_COMPLETED',sourceHTTP:0,MAIN:0,Telegram:0,d1:db.usageSnapshot(),historical_flow:rows.map(r=>({contract:r.contract,status:r.result.status,blocking_checks:r.result.blocking_checks}))}));
